<?php
namespace App\Http\Controllers;use App\Jobs\MatchResumeToHrJobs;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CandidateAutoApplyController extends Controller{public function update(Request $r){abort_unless($r->user()->role_code===1||$r->user()->role==='student',403);$d=$r->validate(['enabled'=>'nullable|boolean','minimum_match_score'=>'required|integer|min:50|max:100','daily_limit'=>'required|integer|min:1|max:10']);$enabled=$r->boolean('enabled');DB::table('candidate_auto_apply_preferences')->updateOrInsert(['user_id'=>$r->user()->id],['enabled'=>$enabled,'minimum_match_score'=>$d['minimum_match_score'],'daily_limit'=>$d['daily_limit'],'consented_at'=>$enabled?now():null,'created_at'=>now(),'updated_at'=>now()]);$resume=$r->user()->candidateProfile?->resumes()->where('is_primary',true)->latest()->first();if($enabled&&$resume)app()->isLocal()?MatchResumeToHrJobs::dispatchSync($resume->id):MatchResumeToHrJobs::dispatch($resume->id)->onQueue('resume-processing');return back()->with('success',$enabled?'Skill matching and internal auto-apply are enabled.':'Automatic applications are disabled.');}}
